const parseNumber = value => (typeof value === 'number' || (typeof value === 'string' && value.trim() !== '' && /^[-+]?\d+(?:\.\d+)?$/.test(value.trim()))) ? Number(value) : NaN;
const rows = $input.all().map(item => item.json);
const expected = $('Sample product IDs').all().map(item => item.json.source_id);
if (rows.length !== expected.length || new Set(rows.map(d => d.id)).size !== expected.length || rows.some(d => !expected.includes(d.id))) throw new Error('Incomplete or mismatched API product batch');
const seen = new Set();
return rows.map(d => {
  const sku = String(d.article ?? '').trim();
  const name = String(d.name ?? '').trim();
  const price = parseNumber(d.price);
  const stock = parseNumber(d.quantity);
  const productUrl = String(d.url ?? '').trim();
  if (!sku || !name || d.price == null || d.quantity == null || seen.has(sku) || !Number.isFinite(price) || price < 0 || !Number.isInteger(stock) || stock < 0 || !productUrl.startsWith('https://ekt.kz/catalog/')) {
    throw new Error('Invalid product detail for id ' + String(d.id ?? '?'));
  }
  seen.add(sku);
  const path = productUrl.slice('https://ekt.kz'.length).split('/').filter(Boolean);
  const category = path.slice(1, -1).join('/') || 'uncategorized';
  const byWarehouse = {};
  for (const store of Array.isArray(d.stores) ? d.stores : []) {
    const warehouse = String(store.name ?? '').trim();
    const quantity = parseNumber(store.quantity);
    if (!warehouse || !Number.isInteger(quantity) || quantity < 0) throw new Error('Invalid warehouse stock for id ' + String(d.id));
    byWarehouse[warehouse] = quantity;
  }
  const attributes = { ...(d.properties && typeof d.properties === 'object' ? d.properties : {}), description: d.description ?? null, image_url: d.image ?? null, source_id: d.id, category_source: 'url_path', api_offers: Array.isArray(d.offers) ? d.offers : [] };
  return { json: { sku, name, category, price, stock_total: stock, stock_by_warehouse: byWarehouse, attributes, certificate_url: null, product_url: productUrl } };
});
